package com.englishhero.reading.translation;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;
class SelectionTranslationIT extends SelectionTranslationHttpITSupport {
 @Test void selectedWordFragmentCanTranslateButGrammarStillRequiresTwoWords()throws Exception{
  var a=actor(true);var u=actor(false);var input=new LinkedHashMap<>(published(a));input.put("text","mar");input.put("requestId",UUID.randomUUID().toString());
  var response=call(u,"POST","/reading/selection-translations",input);assertThat(response.statusCode()).isEqualTo(200);var task=json.readTree(response.body());assertThat(task.path("sourceCharacters").asInt()).isEqualTo(3);var job=jobs.claim().orElseThrow();jobs.completeBaidu(job,new BaiduTranslationClient.Result("损害"));
  input.put("requestId",UUID.randomUUID().toString());assertThat(json.readTree(call(u,"POST","/reading/selection-translations",input).body()).path("id").asText()).isEqualTo(task.path("id").asText());
  input.put("requestId",UUID.randomUUID().toString());input.put("mode","GRAMMAR");assertThat(call(u,"POST","/reading/selection-translations",input).statusCode()).isEqualTo(400);
  input.put("requestId",UUID.randomUUID().toString());input.put("mode","TRANSLATION");input.put("text","zzzxxyy");assertThat(call(u,"POST","/reading/selection-translations",input).statusCode()).isEqualTo(400);
 }
 @Test void grammarHasSeparateCacheAndSharedBudgetAndPrivateStructuredResult()throws Exception{
  var admin=actor(true);var user=actor(false);var other=actor(false);var input=published(admin);String path="/reading/selection-translations";
  String first=json.readTree(call(user,"POST",path,input).body()).path("id").asText();jobs.completeBaidu(jobs.claim().orElseThrow(),new BaiduTranslationClient.Result("当奥马尔搬到新城镇时"));
  var grammar=new LinkedHashMap<>(input);grammar.put("mode","GRAMMAR");assertThat(call(user,"POST",path,grammar).statusCode()).isEqualTo(409);
  grammar.put("requestId",UUID.randomUUID().toString());jdbc.update("UPDATE reading_selection_translation SET created_at=DATE_SUB(created_at,INTERVAL 3 SECOND) WHERE id=?",first);
  var response=call(user,"POST",path,grammar);assertThat(response.statusCode()).isEqualTo(200);String id=json.readTree(response.body()).path("id").asText();assertThat(id).isNotEqualTo(first);
  var job=jobs.claim().orElseThrow();assertThat(job.mode()).isEqualTo("GRAMMAR");assertThat(job.reserve()).isEqualTo(10000);
  String analysis="""
  {"scopeNote":"时间状语从句片段，未包含主句。","mainClause":[{"quote":"Omar","role":"从句主语","explanation":"名词。"}],"clauses":[{"quote":"When Omar moved to a new town","role":"时间状语从句","explanation":"when引导。"}],"clauseNote":"当前仅选中了从句。","grammarPoints":[{"quote":"moved to","explanation":"表示搬到。"}]}
  """;
  jobs.complete(job,new com.englishhero.practice.review.DeepSeekReviewClient.TranslationResponse(analysis,"deepseek-flash",300L,200L));var result=json.readTree(call(user,"GET",path+"/"+id,null).body());assertThat(result.path("translation").isNull()).isTrue();assertThat(result.at("/analysis/mainClause/0/quote").asText()).isEqualTo("Omar");assertThat(result.path("mode").asText()).isEqualTo("GRAMMAR");assertThat(call(other,"GET",path+"/"+id,null).statusCode()).isEqualTo(404);
  grammar.put("requestId",UUID.randomUUID().toString());assertThat(json.readTree(call(user,"POST",path,grammar).body()).path("id").asText()).isEqualTo(id);
  var invalid=new LinkedHashMap<>(grammar);invalid.put("mode","CHAT");invalid.put("requestId",UUID.randomUUID().toString());assertThat(call(user,"POST",path,invalid).statusCode()).isEqualTo(400);
 }
 @Test void validatesSourceAndAuthenticatesAndReusesRequests()throws Exception{var admin=actor(true);var user=actor(false);var other=actor(false);var input=published(admin);String path="/reading/selection-translations";assertThat(call(guest(),"POST",path,input).statusCode()).isEqualTo(401);var r=call(user,"POST",path,input);assertThat(r.statusCode()).isEqualTo(200);String id=json.readTree(r.body()).get("id").asText();assertThat(call(user,"POST",path,input).body()).contains("\"id\":\""+id+"\"");assertThat(call(other,"GET",path+"/"+id,null).statusCode()).isEqualTo(404);var changed=new LinkedHashMap<>(input);changed.put("text","Not present in the article");assertThat(call(user,"POST",path,changed).statusCode()).isEqualTo(409);changed.put("requestId",UUID.randomUUID().toString());assertThat(call(user,"POST",path,changed).statusCode()).isEqualTo(400);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM reading_selection_translation WHERE id=?",Integer.class,id)).isEqualTo(1);}
 @org.springframework.beans.factory.annotation.Autowired SelectionTranslationJobs jobs;
 @org.springframework.beans.factory.annotation.Autowired com.englishhero.practice.review.PracticeReviewProperties config;
 @org.springframework.beans.factory.annotation.Autowired BaiduTranslationProperties baidu;
 @Test void queuedBaiduWorkTransfersItsReservationToTheActualDispatchMonth()throws Exception{
  var a=actor(true);var u=actor(false);var input=published(a);var response=json.readTree(call(u,"POST","/reading/selection-translations",input).body());String id=response.path("id").asText();int chars=response.path("sourceCharacters").asInt();var current=java.time.LocalDate.now(java.time.ZoneId.of("Asia/Shanghai")).withDayOfMonth(1);var previous=current.minusMonths(1);jdbc.update("INSERT INTO reading_baidu_monthly_quota(month_start) VALUES(?) ON DUPLICATE KEY UPDATE month_start=VALUES(month_start)",previous);jdbc.update("UPDATE reading_baidu_monthly_quota SET used_characters=used_characters-? WHERE month_start=?",chars,current);jdbc.update("UPDATE reading_baidu_monthly_quota SET used_characters=used_characters+? WHERE month_start=?",chars,previous);jdbc.update("UPDATE reading_selection_translation SET quota_month=? WHERE id=?",previous,id);long oldBefore=jdbc.queryForObject("SELECT used_characters FROM reading_baidu_monthly_quota WHERE month_start=?",Long.class,previous),newBefore=jdbc.queryForObject("SELECT used_characters FROM reading_baidu_monthly_quota WHERE month_start=?",Long.class,current);var job=jobs.claim().orElseThrow();assertThat(job.quotaMonth()).isEqualTo(current);assertThat(jdbc.queryForObject("SELECT used_characters FROM reading_baidu_monthly_quota WHERE month_start=?",Long.class,previous)).isEqualTo(oldBefore-chars);assertThat(jdbc.queryForObject("SELECT used_characters FROM reading_baidu_monthly_quota WHERE month_start=?",Long.class,current)).isEqualTo(newBefore+chars);jobs.completeBaidu(job,new BaiduTranslationClient.Result("当奥马尔搬到新城镇时"));
 }
 @Test void baiduUsesMonthlyCharactersEvenWhenDailyAiBudgetIsZero()throws Exception{
  var admin=actor(true);var u=actor(false);var v=actor(false);var input=published(admin);String path="/reading/selection-translations";var month=java.time.LocalDate.now(java.time.ZoneId.of("Asia/Shanghai")).withDayOfMonth(1);jdbc.update("INSERT INTO reading_baidu_monthly_quota(month_start) VALUES(?) ON DUPLICATE KEY UPDATE month_start=VALUES(month_start)",month);long before=jdbc.queryForObject("SELECT used_characters FROM reading_baidu_monthly_quota WHERE month_start=?",Long.class,month),old=baidu.getMonthlyCharacterLimit(),oldCny=config.getDailyBudgetMicrocny();int chars=((String)input.get("text")).length();try{config.setDailyBudgetMicrocny(0);baidu.setMonthlyCharacterLimit(before+chars);try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var a=pool.submit(()->call(u,"POST",path,input));var b=pool.submit(()->call(v,"POST",path,input));var first=a.get();var second=b.get();assertThat(List.of(first.statusCode(),second.statusCode())).containsExactlyInAnyOrder(200,429);var result=json.readTree((first.statusCode()==200?first:second).body());assertThat(result.path("model").asText()).isEqualTo("baidu-general");assertThat(result.path("estimatedCostMicrocny").asLong()).isZero();assertThat(result.path("sourceCharacters").asInt()).isEqualTo(chars);}assertThat(jdbc.queryForObject("SELECT used_characters FROM reading_baidu_monthly_quota WHERE month_start=?",Long.class,month)).isEqualTo(before+chars);}finally{baidu.setMonthlyCharacterLimit(old);config.setDailyBudgetMicrocny(oldCny);}
 }
 @Test void previousMonthQueueIsReleasedWithoutDispatchWhenCurrentMonthHasNoRoom()throws Exception{
  var a=actor(true);var u=actor(false);var input=published(a);var response=json.readTree(call(u,"POST","/reading/selection-translations",input).body());String id=response.path("id").asText();int chars=response.path("sourceCharacters").asInt();var current=java.time.LocalDate.now(java.time.ZoneId.of("Asia/Shanghai")).withDayOfMonth(1);var previous=current.minusMonths(1);jdbc.update("INSERT INTO reading_baidu_monthly_quota(month_start) VALUES(?) ON DUPLICATE KEY UPDATE month_start=VALUES(month_start)",previous);jdbc.update("UPDATE reading_baidu_monthly_quota SET used_characters=used_characters-? WHERE month_start=?",chars,current);jdbc.update("UPDATE reading_baidu_monthly_quota SET used_characters=used_characters+? WHERE month_start=?",chars,previous);jdbc.update("UPDATE reading_selection_translation SET quota_month=? WHERE id=?",previous,id);long old=baidu.getMonthlyCharacterLimit(),before=jdbc.queryForObject("SELECT used_characters FROM reading_baidu_monthly_quota WHERE month_start=?",Long.class,previous),used=jdbc.queryForObject("SELECT used_characters FROM reading_baidu_monthly_quota WHERE month_start=?",Long.class,current);try{baidu.setMonthlyCharacterLimit(used);assertThat(jobs.claim()).isEmpty();assertThat(call(u,"GET","/reading/selection-translations/"+id,null).body()).contains("FAILED","BAIDU_CHARACTER_QUOTA","RELEASED");assertThat(jdbc.queryForObject("SELECT used_characters FROM reading_baidu_monthly_quota WHERE month_start=?",Long.class,previous)).isEqualTo(before-chars);assertThat(jdbc.queryForObject("SELECT used_characters FROM reading_baidu_monthly_quota WHERE month_start=?",Long.class,current)).isEqualTo(used);}finally{baidu.setMonthlyCharacterLimit(old);}
 }
 @Test void successfulTranslationsSettleAndCacheWithoutRepeatedProviderCost()throws Exception{var a=actor(true);var u=actor(false);var input=published(a);String path="/reading/selection-translations";String id=json.readTree(call(u,"POST",path,input).body()).get("id").asText();var job=jobs.claim().orElseThrow();assertThat(job.id()).isEqualTo(Long.parseLong(id));jobs.completeBaidu(job,new BaiduTranslationClient.Result("当奥马尔搬到一个新城镇时"));var r=call(u,"GET",path+"/"+id,null);assertThat(r.body()).contains("SUCCEEDED","当奥马尔","SETTLED");long amount=jdbc.queryForObject("SELECT settled_microusd FROM reading_selection_translation WHERE id=?",Long.class,id);assertThat(amount).isZero();var duplicate=new LinkedHashMap<>(input);duplicate.put("requestId",UUID.randomUUID().toString());assertThat(json.readTree(call(u,"POST",path,duplicate).body()).get("id").asText()).isEqualTo(id);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM reading_selection_translation WHERE id=?",Integer.class,id)).isEqualTo(1);}
 @Test void rejectedUnsentRequestsReleaseAndExpiredRunningRequestsDoNotRetry()throws Exception{var a=actor(true);var u=actor(false);var input=published(a);String id=json.readTree(call(u,"POST","/reading/selection-translations",input).body()).get("id").asText();var job=jobs.claim().orElseThrow();jobs.failBaidu(job,new BaiduTranslationClient.Failure("BAIDU_54003",true));assertThat(jdbc.queryForObject("SELECT settled_microusd FROM reading_selection_translation WHERE id=?",Long.class,id)).isZero();jdbc.update("UPDATE reading_selection_translation SET created_at=DATE_SUB(created_at,INTERVAL 3 SECOND) WHERE id=?",id);var next=new LinkedHashMap<>(input);next.put("requestId",UUID.randomUUID().toString());String second=json.readTree(call(u,"POST","/reading/selection-translations",next).body()).get("id").asText();jobs.claim().orElseThrow();jdbc.update("UPDATE reading_selection_translation SET lease_until='2000-01-01 00:00:00' WHERE id=?",second);jobs.recover();assertThat(jdbc.queryForObject("SELECT error_code FROM reading_selection_translation WHERE id=?",String.class,second)).isEqualTo("OUTCOME_UNKNOWN");assertThat(jdbc.queryForObject("SELECT settled_microusd FROM reading_selection_translation WHERE id=?",Long.class,second)).isZero();assertThat(jobs.claim()).isEmpty();}
 @org.junit.jupiter.api.RepeatedTest(3) void sharedOneYuanBudgetSerializesConcurrentReservations()throws Exception{var a=actor(true);var u=actor(false);var v=actor(false);var input=new LinkedHashMap<>(published(a));input.put("mode","GRAMMAR");var day=java.time.LocalDate.now(java.time.ZoneId.of("Asia/Shanghai"));jdbc.update("INSERT IGNORE INTO practice_ai_daily_budget(budget_day) VALUES(?)",day);long before=jdbc.queryForObject("SELECT used_microusd FROM practice_ai_daily_budget WHERE budget_day=?",Long.class,day),old=config.getDailyBudgetMicrocny();try{config.setDailyBudgetMicrocny(((before+10000)*20+2)/3);try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var x=pool.submit(()->call(u,"POST","/reading/selection-translations",input).statusCode());var y=pool.submit(()->call(v,"POST","/reading/selection-translations",input).statusCode());assertThat(List.of(x.get(),y.get())).containsExactlyInAnyOrder(200,429);}assertThat(jdbc.queryForObject("SELECT used_microusd FROM practice_ai_daily_budget WHERE budget_day=?",Long.class,day)).isEqualTo(before+10000);}finally{config.setDailyBudgetMicrocny(old);}}
}
